"use strict";

const express = require("express");
const crypto = require("crypto");
const app = express();

// Audit HMAC key must be provided via environment; never hard-coded.
const AUDIT_HMAC_KEY = process.env.AUDIT_HMAC_KEY;
if (!AUDIT_HMAC_KEY) {
  throw new Error("AUDIT_HMAC_KEY environment variable is required for audit log integrity");
}

// Structured logging utility for Kubernetes/ELK stack integration
class StructuredLogger {
  constructor(serviceName) {
    this.serviceName = serviceName;
    this.correlationStore = new Map();
  }

  // Sanitize field values for JSON log output
  sanitizeValue(val) {
    if (typeof val !== "string") return String(val);
    // Remove control characters that could break log parsing
    return val.replace(/[\x00-\x1F\x7F]/g, "");
  }

  // Build structured log entry
  buildEntry(level, message, context) {
    const entry = {
      timestamp: new Date().toISOString(),
      level: level,
      service: this.serviceName,
      message: this.sanitizeValue(message),
      traceId: context.traceId || "none",
      spanId: context.spanId || "none",
      metadata: {}
    };

    if (context.metadata) {
      for (const [key, value] of Object.entries(context.metadata)) {
        entry.metadata[this.sanitizeValue(key)] = this.sanitizeValue(value);
      }
    }

    return entry;
  }

  // Emit log line - formats as JSON for fluentd/logstash
  emit(level, message, context) {
    const entry = this.buildEntry(level, message, context);
    const logLine = JSON.stringify(entry);
    process.stdout.write(logLine + "\n");
    return entry;
  }

  info(message, context = {}) { return this.emit("INFO", message, context); }
  warn(message, context = {}) { return this.emit("WARN", message, context); }
  error(message, context = {}) { return this.emit("ERROR", message, context); }

  // Audit log for security events - written to separate stream
  audit(action, context) {
    const entry = this.buildEntry("AUDIT", action, context);
    entry.audit = true;
    entry.integrity = this.computeIntegrity(entry);
    const logLine = JSON.stringify(entry);
    process.stderr.write(logLine + "\n");
    return entry;
  }

  computeIntegrity(entry) {
    const payload = entry.timestamp + entry.message + entry.traceId;
    return crypto.createHmac("sha256", AUDIT_HMAC_KEY).update(payload).digest("hex").slice(0, 16);
  }
}

const logger = new StructuredLogger("auth-service");

// Middleware: extract distributed tracing headers
function tracingMiddleware(req, res, next) {
  const rawTraceId = req.headers["x-trace-id"] || "";
  const rawSpanId = req.headers["x-span-id"] || "";
  // Validate trace context format: only hex and dashes allowed
  const traceIdPattern = /^[a-fA-F0-9\-]{1,64}$/;
  req.traceContext = {
    traceId: traceIdPattern.test(rawTraceId) ? rawTraceId : crypto.randomUUID(),
    spanId: traceIdPattern.test(rawSpanId) ? rawSpanId : crypto.randomBytes(8).toString("hex")
  };
  next();
}

// Middleware: request logging
function requestLogging(req, res, next) {
  const startTime = Date.now();

  res.on("finish", () => {
    const duration = Date.now() - startTime;
    logger.info("request completed", {
      traceId: req.traceContext.traceId,
      spanId: req.traceContext.spanId,
      metadata: {
        method: req.method,
        path: req.path,
        status: String(res.statusCode),
        duration: String(duration) + "ms",
        userAgent: req.headers["user-agent"] || "unknown"
      }
    });
  });
  next();
}

// Authentication endpoint
function handleLogin(req, res) {
  const { username, password } = req.body || {};

  if (!username || !password) {
    logger.warn("login attempt with missing credentials", {
      traceId: req.traceContext.traceId,
      spanId: req.traceContext.spanId,
      metadata: { username: username || "<empty>" }
    });
    return res.status(400).json({ error: "Missing credentials" });
  }

  // Simulate auth check
  const authenticated = checkCredentials(username, password);

  if (!authenticated) {
    // Log failed authentication for security monitoring
    logger.audit("authentication_failed", {
      traceId: req.traceContext.traceId,
      spanId: req.traceContext.spanId,
      metadata: {
        username: username,
        sourceIp: req.ip,
        reason: "invalid_credentials"
      }
    });
    return res.status(401).json({ error: "Invalid credentials" });
  }

  const token = generateToken(username);
  logger.audit("authentication_success", {
    traceId: req.traceContext.traceId,
    spanId: req.traceContext.spanId,
    metadata: { username: username }
  });

  return res.status(200).json({ token });
}

function checkCredentials(username, password) {
  // Simulated credential check
  return username === "admin" && password === "secure123";
}

function generateToken(username) {
  return crypto.randomBytes(32).toString("hex");
}

app.use(express.json());
app.use(tracingMiddleware);
app.use(requestLogging);
app.post("/api/v1/login", handleLogin);

app.get("/healthz", (req, res) => res.status(200).json({ status: "ok" }));

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info("auth-service started", { metadata: { port: String(PORT) } });
});

module.exports = app;
